   var basic=RuleAt("basic",true);string old=FileAt("basic\\old.bin","cached"),recent=FileAt("basic\\recent.bin","fresh");File.SetLastWriteTimeUtc(recent,DateTime.UtcNow);
   var engine=TestEngine(basic);var finding=engine.ScanRule(basic,CancellationToken.None);Assert(finding.Files==2&&finding.Candidates.Count==1&&finding.Recent==1,"Age cutoff retains recent files [files="+finding.Files+", candidates="+finding.Candidates.Count+", recent="+finding.Recent+", links="+finding.Links+", unreadable="+finding.Unreadable+"]");var result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(result.Deleted==1&&!File.Exists(old)&&File.Exists(recent),"Quick cleanup removes only eligible cache");
   var running=RuleAt("running",true);running.Processes=new[]{"fixture-owner"};string runningFile=FileAt("running\\keep.bin","keep");engine=TestEngine(running);engine.IsRunning=owners=>true;finding=engine.ScanRule(running,CancellationToken.None);Assert(finding.Running&&finding.Candidates.Count==0,"Running owner blocks scan candidates");engine.IsRunning=owners=>false;finding=engine.ScanRule(running,CancellationToken.None);engine.IsRunning=owners=>true;result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(File.Exists(runningFile)&&result.Deleted==0&&result.Skipped==1,"Owner started after scan blocks deletion");
   var changed=RuleAt("changed",true);string changedFile=FileAt("changed\\keep.bin","before");engine=TestEngine(changed);finding=engine.ScanRule(changed,CancellationToken.None);File.AppendAllText(changedFile,"after");result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(File.Exists(changedFile)&&result.Deleted==0,"Modified file retained after scan");
   var replaced=RuleAt("replaced",true);string replacedFile=FileAt("replaced\\same.bin","original");engine=TestEngine(replaced);finding=engine.ScanRule(replaced,CancellationToken.None);DateTime oldTime=File.GetLastWriteTimeUtc(replacedFile);File.Move(replacedFile,Path.Combine(fixture,"moved-original.bin"));File.WriteAllText(replacedFile,"original");File.SetLastWriteTimeUtc(replacedFile,oldTime);result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(File.Exists(replacedFile)&&result.Deleted==0,"Replaced file rejected even with same size and timestamp");
   var locked=RuleAt("locked",true);string lockedFile=FileAt("locked\\keep.bin","locked");engine=TestEngine(locked);finding=engine.ScanRule(locked,CancellationToken.None);using(var held=File.Open(lockedFile,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){result=engine.Clean(new[]{finding},true,CancellationToken.None,null);}Assert(File.Exists(lockedFile)&&result.Deleted==0,"Locked file safely skipped");
   var readOnly=RuleAt("readonly",true);string readOnlyFile=FileAt("readonly\\keep.bin","readonly");engine=TestEngine(readOnly);finding=engine.ScanRule(readOnly,CancellationToken.None);File.SetAttributes(readOnlyFile,FileAttributes.ReadOnly);result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(File.Exists(readOnlyFile)&&result.Deleted==0,"Read-only file retained without permission changes");
   var manual=RuleAt("manual",false);string manualFile=FileAt("manual\\keep.bin","manual");engine=TestEngine(manual);finding=engine.ScanRule(manual,CancellationToken.None);result=engine.Clean(new[]{finding},true,CancellationToken.None,null);Assert(File.Exists(manualFile)&&result.Deleted==0,"Manual category excluded from quick cleanup");result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(!File.Exists(manualFile)&&result.Deleted==1,"Explicit advanced selection supports manual category");
   var protectedRule=RuleAt("protected",true);protectedRule.Protected=true;string protectedFile=FileAt("protected\\settings.json","user data");engine=TestEngine(protectedRule);finding=engine.ScanRule(protectedRule,CancellationToken.None);finding.Candidates.Add(new Snapshot {Path=protectedFile});result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(File.Exists(protectedFile)&&result.Deleted==0,"Protected category cannot be deleted");
   var scoped=RuleAt("scoped",true);FileAt("scoped\\safe.bin","safe");string outside=FileAt("scoped-neighbor\\document.txt","personal");engine=TestEngine(scoped);finding=engine.ScanRule(scoped,CancellationToken.None);finding.Candidates.Clear();finding.Candidates.Add(new Snapshot {Path=outside});result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(File.Exists(outside)&&result.Deleted==0,"Sibling directory prefix cannot escape allowed scope");Assert(!Engine.InScope(scoped,Path.Combine(fixture,"scoped\\..\\scoped-neighbor\\document.txt")),"Parent traversal rejected after normalization");
   var extension=RuleAt("extension",false);extension.Extensions=new[]{".exe"};string installer=FileAt("extension\\installer.exe","installer"),binary=FileAt("extension\\program.dll","program");engine=TestEngine(extension);finding=engine.ScanRule(extension,CancellationToken.None);Assert(finding.Candidates.Count==1&&finding.Candidates[0].Path==installer,"Update rule only selects approved package types");result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(!File.Exists(installer)&&File.Exists(binary),"Installed-looking binary retained under updater root");
   var links=RuleAt("hardlinks",true);Directory.CreateDirectory(links.Roots[0]);string personal=FileAt("personal\\keep.txt","important"),hardlink=Path.Combine(links.Roots[0],"linked.bin");Assert(CreateHardLink(hardlink,personal,IntPtr.Zero),"Hardlink fixture created");engine=TestEngine(links);finding=engine.ScanRule(links,CancellationToken.None);Assert(finding.Candidates.Count==0&&finding.Links==1,"Hardlinks excluded to protect shared files");Assert(File.Exists(personal)&&File.Exists(hardlink),"Hardlink target remains untouched");
   var junction=RuleAt("junction",true);Directory.CreateDirectory(junction.Roots[0]);string linkedDir=Path.Combine(junction.Roots[0],"linked-directory"),targetDir=Path.Combine(fixture,"personal");string escapedLink=linkedDir.Replace("'","''"),escapedTarget=targetDir.Replace("'","''");
   var junctionProcess=Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -Command \"New-Item -ItemType Junction -Path '"+escapedLink+"' -Target '"+escapedTarget+"' | Out-Null\""){UseShellExecute=false,CreateNoWindow=true});junctionProcess.WaitForExit();Assert(junctionProcess.ExitCode==0,"Junction fixture created");engine=TestEngine(junction);finding=engine.ScanRule(junction,CancellationToken.None);Assert(finding.Links==1&&finding.Candidates.Count==0,"Directory junction not traversed");Assert(File.Exists(personal),"Linked personal directory remains intact");
   var cancelled=RuleAt("cancelled",true);string cancelledFile=FileAt("cancelled\\keep.bin","keep");engine=TestEngine(cancelled);finding=engine.ScanRule(cancelled,CancellationToken.None);var stop=new CancellationTokenSource();stop.Cancel();result=engine.Clean(new[]{finding},true,stop.Token,null);Assert(result.Cancelled&&File.Exists(cancelledFile),"Cancelled cleanup retains unprocessed files");
   var single=RuleAt("single",false);single.Single=true;single.Roots=new[]{FileAt("single\\MEMORY.DMP","dump")};string adjacent=FileAt("single\\pagefile.sys","system");engine=TestEngine(single);finding=engine.ScanRule(single,CancellationToken.None);result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(result.Deleted==1&&File.Exists(adjacent),"Single-file cleanup cannot touch adjacent system files");
   var failedScope=RuleAt("unknown",true);FileAt("unknown\\keep.bin","keep");engine=TestEngine();finding=new Finding {Rule=failedScope};finding.Candidates.Add(new Snapshot {Path=Path.Combine(fixture,"unknown\\keep.bin")});result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(result.Deleted==0,"Unregistered rules cannot delete files");
   var top=RuleAt("top-only",false);top.OnlyTop=true;top.Extensions=new[]{".db"};top.NamePrefix="thumbcache_";
   string thumbnail=FileAt("top-only\\thumbcache_256.db","cache"),icon=FileAt("top-only\\iconcache.db","keep"),nested=FileAt("top-only\\nested\\thumbcache_256.db","keep"),otherType=FileAt("top-only\\thumbcache_notes.txt","keep");
   engine=TestEngine(top);finding=engine.ScanRule(top,CancellationToken.None);Assert(finding.Candidates.Count==1&&finding.Candidates[0].Path==thumbnail,"Thumbnail rule requires approved filename and extension");Assert(!Engine.InScope(top,nested),"Top-level-only rule rejects nested file even at deletion boundary");result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(!File.Exists(thumbnail)&&File.Exists(icon)&&File.Exists(nested)&&File.Exists(otherType),"Thumbnail cleanup preserves icon database and nested data");
   var notice=RuleAt("notice",false);notice.Protected=true;notice.Notice=true;engine=TestEngine(notice);Assert(engine.Scan(CancellationToken.None,null).Count==1,"Protected explanations remain visible when no files exist");
   string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows),missing=Path.Combine(RuleBook.TargetDrive,"ClearSpace-Nonexistent-"+Guid.NewGuid().ToString("N"),"app.exe");
   string otherDrive=String.Equals(RuleBook.TargetDrive,"Z:\\",StringComparison.OrdinalIgnoreCase)?"Y:\\":"Z:\\";
   Assert(ShortcutAudit.ProvenMissingLocalTarget(missing)&&!ShortcutAudit.ProvenMissingLocalTarget(windows),"Shortcut audit distinguishes proved missing and existing local targets");Assert(!ShortcutAudit.ProvenMissingLocalTarget("\\\\nonexistent-server\\share\\app.exe")&&!ShortcutAudit.ProvenMissingLocalTarget("relative.exe")&&!ShortcutAudit.ProvenMissingLocalTarget(Path.Combine(otherDrive,"ClearSpace-Nonexistent-"+Guid.NewGuid().ToString("N"),"absent.exe")),"Shortcut audit excludes network, relative and other-drive targets");
   var shortcut=RuleAt("shortcuts",false);shortcut.Shortcut=true;shortcut.Extensions=new[]{".lnk"};string invalid=LinkAt("shortcuts\\missing.lnk",missing),valid=LinkAt("shortcuts\\valid.lnk",windows);
   engine=TestEngine(shortcut);finding=engine.ScanRule(shortcut,CancellationToken.None);Assert(finding.Candidates.Count==1&&finding.Candidates[0].Path==invalid&&finding.Candidates[0].Condition==missing,"Shortcut candidates require read-only verified missing targets");finding.Candidates[0].Condition=windows;result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(result.Deleted==0&&File.Exists(invalid),"Deletion rechecks shortcut target and retains restored or uncertain targets");finding=engine.ScanRule(shortcut,CancellationToken.None);result=engine.Clean(new[]{finding},false,CancellationToken.None,null);Assert(result.Deleted==1&&!File.Exists(invalid)&&File.Exists(valid),"Advanced shortcut cleanup removes only verified invalid fixture links");
   var catalog=RuleBook.Create();Assert(catalog.Select(r=>r.Group).Distinct().Count()==9&&new[]{"code-cache","wechat-web","qq-web","adobe-media","wps-http-cache","chrome","edge","firefox"}.All(id=>catalog.Any(r=>r.Id==id)),"Curated catalog covers nine categories and common application caches");Assert(catalog.Where(r=>r.InfoKind=="storage").All(r=>r.Protected&&!r.Quick)&&catalog.Where(r=>r.InfoKind=="registry-clean").All(r=>!r.Quick),"Registry is excluded from one-click and Windows-managed content is protected");Assert(catalog.Select(r=>r.Id).Distinct().Count()==catalog.Count,"Expanded rule identifiers are unique");
